#!/usr/bin/env bash
# Deploy the app to Railway: one container running TuringDB with the graph
# loaded and the app's Express server (see Dockerfile).
#
# app/ is generated by `kit sync` from a private repo and the CSV files live in
# git LFS, so Railway cannot build from the GitHub repo. This script instead
# syncs app/ as run.sh does, stages a minimal build context (no node_modules,
# no .turing, no raw data) and uploads it with `railway up`.
#
#   ./deploy.sh            stage and deploy to the linked Railway service
#   ./deploy.sh --docker   stage and build the image locally (tag uktransport)
#
# Environment overrides:
#   KIT                turingdb-ui-kit checkout to use instead of the submodule
#   SYNC=0             skip `kit sync` (app/ must already exist)
#   RAILWAY_SERVICE    service to deploy to (default: the linked service)
#
# The service settings (health check) live in .railway/railway.ts: apply
# changes to them with `railway config apply`.

set -euo pipefail

DEMO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
KIT="${KIT:-$DEMO_DIR/turingdb-ui-kit}"

TARGET="railway"
for arg in "$@"; do
    case "$arg" in
        --docker) TARGET="docker" ;;
        *)
            echo "usage: deploy.sh [--docker]" >&2
            exit 1
        ;;
    esac
done

cd "$DEMO_DIR"

if [[ "$KIT" == "$DEMO_DIR/turingdb-ui-kit" ]]; then
    git submodule update --init --recursive
fi
if [[ "${SYNC:-1}" != "0" || ! -d app ]]; then
    node "$KIT/tools/kit.mjs" sync "$DEMO_DIR"
fi

# git LFS leaves small pointer files when the objects were not pulled.
for csv in data/*.csv; do
    if head -c 100 "$csv" | grep -q '^version https://git-lfs'; then
        echo "deploy.sh: $csv is a git LFS pointer, run: git lfs pull" >&2
        exit 1
    fi
done

STAGE="$(mktemp -d "${TMPDIR:-/tmp}/uktransport-deploy-XXXXXX")"
trap 'rm -rf "$STAGE"' EXIT

cp -r Dockerfile deploy fetch.py pyproject.toml uv.lock "$STAGE"/
mkdir "$STAGE/data"
cp data/*.csv "$STAGE/data"/
tar -C app --exclude=./node_modules --exclude=./dist --exclude=./.git \
    --exclude=./test-results --exclude=./playwright-report -cf - . \
    | tar -C "$STAGE" --one-top-level=app -xf -
echo "deploy.sh: staged $(du -sh "$STAGE" | cut -f1) in $STAGE"

if [[ "$TARGET" == "docker" ]]; then
    docker build -t uktransport "$STAGE"
    echo "deploy.sh: built image uktransport, run it with:"
    echo "  docker run --rm -p 8080:8080 uktransport"
    exit 0
fi

railway up "$STAGE" --path-as-root --ci \
    ${RAILWAY_SERVICE:+--service "$RAILWAY_SERVICE"} \
    --message "deploy $(git rev-parse --short HEAD)$(git diff --quiet HEAD || echo '-dirty')"
